INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷78·晋高祖纪·天福四年闰七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c95625692d30c3a868c0e61b35b6fb0ce80c9c44/content/books/zizhi-tongjian/vol-282/year-0939/part-03/sources/library/jiuwudaishi-078-intercalary-july/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年闰七月，段落 jiu-wudaishi-205deb4a7860-p001934；已核上下文及传主，纸本及异文待核。", "id": "8efd5b98-dbff-50a0-b907-edd3238b8632"}, {"title": "旧五代史·卷78·晋高祖纪·天福四年七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c95625692d30c3a868c0e61b35b6fb0ce80c9c44/content/books/zizhi-tongjian/vol-282/year-0939/part-03/sources/library/jiuwudaishi-078-july/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年七月，段落 jiu-wudaishi-205deb4a7860-p001933；已核上下文及传主，纸本及异文待核。", "id": "6bff813a-4b17-51b7-bee6-bc275a6d2d14"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c95625692d30c3a868c0e61b35b6fb0ce80c9c44/content/books/zizhi-tongjian/vol-282/year-0939/part-03/sources/library/tongjian-282-939-intercalary/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003350；电子底本待考，分段待核", "id": "b35bc732-9e6a-58d7-bd84-58ffa2046472"}, {"title": "新五代史·卷51·安重荣传", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c95625692d30c3a868c0e61b35b6fb0ce80c9c44/content/books/zizhi-tongjian/vol-282/year-0939/part-03/sources/library/xinwudaishi-051-an-chongrong/source.txt", "note": "《新五代史》卷51·安重荣传，段落 xin-wudaishi-b08f244b9241-p002001；已核上下文及传主，纸本及异文待核。", "id": "66f6cc63-cc75-5b6c-ad13-c61abfde870c"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00e77c12d50b6f8ea7c868872b15b90ddf01b8db/content/books/zizhi-tongjian/vol-282/year-0939/part-02/sources/library/tongjian-282-939-spring-summer/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003349；电子底本待考，分段待核", "id": "78a64ddf-01ce-59c9-8104-c62aada229dd"}, {"title": "旧五代史·卷88·王庭胤传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38057258b21c79a77db1740bb23708c7e75c602c/content/books/zizhi-tongjian/vol-281/year-0938/part-07/sources/library/jiuwudaishi-088-wang-tingyin/source.txt", "note": "《旧五代史》卷88·王庭胤传，段落 jiu-wudaishi-205deb4a7860-p002097；已核上下文及传主，纸本及异文待核。", "id": "8cf20a86-f3f7-5f9d-a272-cdf04679008d"}]'::jsonb)
