INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "秘琼", "aliases": ["秘瓊", "祕瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：秘琼，平山籍、牙内都虞侯、受倚者。", "biography": null, "status": "draft", "id": "8ce65f13-6a07-5795-bdb6-565c3af0ff0d"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "薛融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：薛融，自述者。", "biography": null, "status": "draft", "id": "88010995-da61-5a9b-b48e-735ca607d915"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "王威（王处直之子）", "aliases": ["王威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》与《旧五代史》记为王处直之子，因王都夺权逃往契丹。939年契丹要求后晋让他承袭父亲旧地，石敬瑭拒绝直接授节度使。生卒年未载。是否与早期记载的王郁有关，尚待校核，未作合并。", "biography": null, "status": "draft", "id": "b8e709ed-276d-5351-9197-53ae1516325e"}, {"name": "王处直", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "d9976684-5d65-5264-903f-d1131632e4f3"}, {"name": "王都", "aliases": ["刘云郎", "劉雲郎", "云郎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271龙德元年条所见人物：王都。", "biography": null, "status": "draft", "id": "e990d522-e16a-5709-b3a3-fd6ccf95796b"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "王廷胤", "aliases": ["王庭胤", "王庭允"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王处存的孙子，曾任贝州防御使。938年任彰德军节度使。《旧五代史》传记作王庭胤，记他字绍基，祖籍长安；同一传记及任官纪事又作王庭允。", "biography": null, "status": "draft", "id": "84bebd8d-f76c-5a88-8a58-3932dce9cb0c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "七月初一发生日食", "start_year": 939, "end_year": 939, "time_original": "939年七月庚子朔", "dynasty": "五代十国", "description": "《资治通鉴》记，七月初一发生日食。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b7fdd369-f8b2-5c23-8af8-947714e98ada"}, {"title": "史书追述安重荣出身军伍，并批评他的作风", "start_year": null, "end_year": null, "time_original": "安重荣此前的经历与作风概述，具体日期未载", "dynasty": "五代十国", "description": "《资治通鉴》记，成德节度使安重荣出身军伍，性情粗率，并用恃勇骄暴评价他的作风。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "27e0e93e-8c34-505e-9969-b06df78a834d"}, {"title": "安重荣声称兵强马壮就能成为天子", "start_year": null, "end_year": null, "time_original": "安重荣此前多次言论，具体日期未载", "dynasty": "五代十国", "description": "安重荣声称兵强马壮就能成为天子。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c9f703e6-a396-5f5c-8068-a8184e444d82"}, {"title": "安重荣射中幡竿龙首，自认为有天命", "start_year": null, "end_year": null, "time_original": "安重荣此前射箭的追述，具体日期未载", "dynasty": "五代十国", "description": "安重荣官署有高数十尺的幡竿。他声称如果能射中竿上的龙首，就证明自己有天命；一箭射中后，他更加自负。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "872632ab-6615-57a4-9fad-726ea4ed6995"}, {"title": "石敬瑭曾告诫安重荣，秘琼若拒绝交接，不要武力夺镇", "start_year": null, "end_year": null, "time_original": "安重荣接替秘琼之前的追述，非939年新任命", "dynasty": "五代十国", "description": "石敬瑭派安重荣接替秘琼时曾告诫：如果秘琼不肯交接，就另给安重荣一个军镇，不要武力夺取，以免事态扩大。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b62b9aa6-01cb-5fa7-99bc-e787323f19fe"}, {"title": "安重荣把石敬瑭的交接告诫视为怯懦", "start_year": null, "end_year": null, "time_original": "安重荣听到交接告诫后的言论，具体日期未载", "dynasty": "五代十国", "description": "安重荣因此认为石敬瑭怯懦，并声称：皇帝连秘琼都畏惧，更何况拥有将相地位和众多兵马的自己。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f6a5a046-6755-5a73-a300-6404638f828a"}, {"title": "安重荣因奏请受限制而不满，招集亡命者并购买战马", "start_year": null, "end_year": null, "time_original": "七月调任皇甫遇之前的持续动向，起止日期未载", "dynasty": "五代十国", "description": "《资治通鉴》记，安重荣的奏请常超过分限，受到执政者审核和限制。他心怀不满，招集亡命者、购买战马，并生出不安于现状的野心。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4d72bc7d-96c3-530a-803c-ffdc325dd315"}, {"title": "石敬瑭将安重荣的姻亲皇甫遇调任昭义节度使", "start_year": 939, "end_year": 939, "time_original": "939年七月甲辰", "dynasty": "五代十国", "description": "石敬瑭得知安重荣的动向。义武节度使皇甫遇与安重荣是姻亲，皇帝在甲辰将皇甫遇调任昭义节度使。", "phases": [], "location_name": "义武、昭义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e41321ea-e08a-5e37-94ca-f04a142f5339"}, {"title": "闽国北宫起火，宫殿几乎全部烧毁", "start_year": 939, "end_year": 939, "time_original": "939年七月乙巳", "dynasty": "五代十国", "description": "闽国北宫起火，宫殿几乎全部烧毁。", "phases": [], "location_name": "闽国北宫", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eb6bc84d-3eab-569a-b77b-52525c666cdf"}, {"title": "薛融等呈上整理的编敕，朝廷颁行", "start_year": 939, "end_year": 939, "time_original": "939年七月戊申", "dynasty": "五代十国", "description": "薛融等呈上整理完成的编敕，朝廷随后颁行。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ddbc40b5-227a-5fc6-b30b-ed148c00469c"}, {"title": "石敬瑭禁止私人铸钱，改由官府专铸", "start_year": 939, "end_year": 939, "time_original": "939年七月丙辰；《旧五代史》另记七月戊申", "dynasty": "五代十国", "description": "石敬瑭下诏称，此前允许公私铸钱，但私铸钱多掺铅锡，钱体小、薄、残缺，因此禁止私人铸钱，改由官府专铸。《资治通鉴》记诏令在七月丙辰，《旧五代史》记在戊申，两书纪日不同。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0b3ff585-1bfd-574f-9679-0720762bff31"}, {"title": "杨光远上疏指责桑维翰任免不公，并经营商铺与民争利", "start_year": 939, "end_year": 939, "time_original": "939年桑维翰外任之前，具体月日未载", "dynasty": "五代十国", "description": "西京留守杨光远上疏，指责中书侍郎、同平章事桑维翰任免官员不公，并在两都经营商铺、与民争利。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "145c9480-a409-5e6e-963b-81f80bd665e1"}, {"title": "石敬瑭将桑维翰调任彰德节度使、兼侍中", "start_year": 939, "end_year": 939, "time_original": "939年闰七月壬申", "dynasty": "五代十国", "description": "杨光远上疏后，石敬瑭在闰七月壬申将桑维翰调任彰德节度使、兼侍中。《资治通鉴》将皇帝的处置描述为不得已。", "phases": [], "location_name": "彰德", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "84f7fd0c-7edf-58d6-bdbe-1dc573e6f1bd"}, {"title": "史书追述王处直之子王威因王都夺权逃往契丹", "start_year": null, "end_year": 